package com.gmail.manhle240406.project.extensions;
import org.junit.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;
public class ExtensionContractsTest {
 @Test public void leaseUsesSameBootElapsedTimeAndNeverWallClock(){assertTrue(OfflineLease.valid(1000,2000,7,7,3600000));assertFalse(OfflineLease.valid(1000,999,7,7,3600000));assertFalse(OfflineLease.valid(1000,2000,7,8,3600000));assertFalse(OfflineLease.valid(0,OfflineLease.MAX_MILLIS,7,7,OfflineLease.MAX_MILLIS));assertFalse(OfflineLease.valid(0,1,-1,-1,100));}
 @Test public void dstGapRejectsRatherThanPrescribingShift(){assertThrows(IllegalArgumentException.class,()->ReminderTime.resolve("2026-03-08","02:30","America/New_York",null));}
 @Test public void ambiguousTimeRequiresExplicitOffset(){assertThrows(IllegalArgumentException.class,()->ReminderTime.resolve("2026-11-01","01:30","America/New_York",null));Instant first=ReminderTime.resolve("2026-11-01","01:30","America/New_York",-240),last=ReminderTime.resolve("2026-11-01","01:30","America/New_York",-300);assertEquals(3600,last.getEpochSecond()-first.getEpochSecond());}
 @Test public void unknownOffsetAndImpossibleDateReject(){assertThrows(RuntimeException.class,()->ReminderTime.resolve("2026-02-30","09:00","UTC",null));assertThrows(IllegalArgumentException.class,()->ReminderTime.resolve("2026-10-01","09:00","Asia/Bangkok",0));}
 @Test public void pureRankingUsesExplicitFourTwoOneAndNoUnavailablePets(){DiscoveryTools.Candidate a=new DiscoveryTools.Candidate("a","cat","hanoi",Set.of("quiet"),1,true),b=new DiscoveryTools.Candidate("b","cat","hcm",Set.of(),2,true),c=new DiscoveryTools.Candidate("c","cat","hanoi",Set.of("quiet"),3,false);List<DiscoveryTools.Ranked> ranked=DiscoveryTools.rank(Arrays.asList(b,c,a),true,Set.of("cat"),Set.of("hanoi"),Set.of("quiet"));assertEquals(2,ranked.size());assertEquals("a",ranked.get(0).candidate.id);assertEquals(7,ranked.get(0).score);assertEquals(2,ranked.get(0).reasons.size());assertEquals(4,ranked.get(1).score);}
 @Test public void optOutReturnsNewestNoReasonsAndCapsWindow(){DiscoveryTools.Candidate a=new DiscoveryTools.Candidate("a","cat","hanoi",Set.of(),1,true),b=new DiscoveryTools.Candidate("b","dog","hcm",Set.of(),2,true);List<DiscoveryTools.Ranked> ranked=DiscoveryTools.rank(Arrays.asList(a,b),false,Set.of("cat"),Set.of(),Set.of());assertEquals("b",ranked.get(0).candidate.id);assertEquals(0,ranked.get(0).score);assertTrue(ranked.get(0).reasons.isEmpty());assertThrows(IllegalArgumentException.class,()->DiscoveryTools.rank(Collections.nCopies(61,a),true,Set.of(),Set.of(),Set.of()));}
 @Test public void nearbyLabelsCoarseBandsAndTransientOriginExpires(){assertEquals("under_5km",DiscoveryTools.distanceBand(0,0,0,0));assertEquals("25km_plus",DiscoveryTools.distanceBand(0,0,1,0));assertNull(DiscoveryTools.distanceBand(Double.NaN,0,0,0));DiscoveryTools.RequestGeneration state=new DiscoveryTools.RequestGeneration();state.transientOrigin(0,0,100);assertEquals("under_5km",state.band(0,0,200));assertNull(state.band(0,0,300100));state.clear();assertNull(state.band(0,0,100));}
 @Test public void oneQueryAtATimeAndOldCallbackCannotClearNewRequest(){DiscoveryTools.RequestGeneration state=new DiscoveryTools.RequestGeneration();long old=state.begin();assertThrows(IllegalStateException.class,state::begin);state.reset();long current=state.begin();assertFalse(state.complete(old));assertThrows(IllegalStateException.class,state::begin);assertTrue(state.complete(current));}
}
